num = strNum.toString().replace(/\$|\,/g,'');	if(isNaN(num))		num = "0";	return num;}function formatCurrency(InpunObject) {	num = InpunObject.value;	num = num.toString().replace(/\$|\,/g,'');	if(isNaN(num))		num = "0";	sign = (num == (num = Math.abs(num)));	num = Math.floor(num*100+0.50000000001);	cents = num%100;	num = Math.floor(num/100).toString();	if(cents<10)	cents = "0" + cents;	for (var i = 0; i < Math.floor((num.length-(1+i))/3); i++)		num = num.substring(0,num.length-(4*i+3))+','+	num.substring(num.length-(4*i+3));	InpunObject.value = (((sign)?'':'-') + '$' + num + '.' + cents);}function calculatotal(value, cont){	var TotalSinIva = 0;	var Iva = 0;	TotalFactura = 0;		for(i=1;i<= document.frm.ITEM.value;i++){		if(document.frm.elements["ValorU"+i].value  != '' && document.frm.elements["Cantidad"+i].value != '')		{				var total = getNum(document.frm.elements["Cantidad"+i].value) * getNum(document.frm.elements["ValorU"+i].value);			document.frm.elements["Total"+i].value = total;			formatCurrency(document.frm.elements["Total"+i]);						TotalSinIva = TotalSinIva + total;						Iva = Iva + ( ((getNum(document.frm.elements["Precio"+i].value)*1) - (getNum(document.frm.elements["ValorU"+i].value)*1)) * (getNum(document.frm.elements["Cantidad"+i].value)*1) )					}	}		TotalFactura = TotalSinIva + Iva;	document.frm.elements["TotalSinIVA"].value = TotalSinIva;	formatCurrency(document.frm.elements["TotalSinIVA"]);		document.frm.elements["ValorIVA"].value = Iva;	formatCurrency(document.frm.elements["ValorIVA"]);		document.frm.elements["ValorTotal"].value = TotalFactura;	formatCurrency(document.frm.elements["ValorTotal"]);	}			/*var totalsiniva = (getNum(document.frm.elements["TotalSinIVA"].value)*1) + (getNum(total)*1);	document.frm.elements["TotalSinIVA"].value = totalsiniva;		var iva = ((getNum(document.frm.elements["Precio"+cont].value)*1) - (getNum(document.frm.elements["ValorU"+cont].value)*1)) * (ge